using System;
using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

Console.WriteLine($"Runtime: {Environment.Version} ({System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription})");
Console.WriteLine();

var rng = new Random(42);
var small = new TextAnalyzer(GenerateText(rng, 50));
var medium = new TextAnalyzer(GenerateText(rng, 500));
var large = new TextAnalyzer(GenerateText(rng, 5000));

const int warmup = 500;
const int iterations = 5000;

// Warmup + bench each method at each size
Console.WriteLine($"{"Method",-35} {"Mean (ns)",12} {"StdDev (ns)",12}  Iterations={iterations}");
Console.WriteLine(new string('-', 72));

Bench("AverageWordLength (50w)",   () => small.AverageWordLength());
Bench("AverageWordLength (500w)",  () => medium.AverageWordLength());
Bench("AverageWordLength (5000w)", () => large.AverageWordLength());
Bench("WordLengthHistogram (50w)",   () => small.WordLengthHistogram());
Bench("WordLengthHistogram (500w)",  () => medium.WordLengthHistogram());
Bench("WordLengthHistogram (5000w)", () => large.WordLengthHistogram());
Bench("UniqueWordCount (50w)",   () => small.UniqueWordCount());
Bench("UniqueWordCount (500w)",  () => medium.UniqueWordCount());
Bench("UniqueWordCount (5000w)", () => large.UniqueWordCount());

static string GenerateText(Random rng, int wordCount)
{
    var words = new string[wordCount];
    for (int i = 0; i < wordCount; i++)
    {
        int len = rng.Next(1, 15);
        var chars = new char[len];
        for (int j = 0; j < len; j++)
            chars[j] = (char)('a' + rng.Next(0, 26));
        words[i] = new string(chars);
    }
    return string.Join(' ', words);
}

[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<object?> action)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Collect individual timings
    var sw = new Stopwatch();
    double[] timings = new double[iterations];
    for (int i = 0; i < iterations; i++)
    {
        sw.Restart();
        action();
        sw.Stop();
        timings[i] = sw.Elapsed.TotalNanoseconds;
    }

    double mean = 0;
    for (int i = 0; i < timings.Length; i++) mean += timings[i];
    mean /= timings.Length;

    double variance = 0;
    for (int i = 0; i < timings.Length; i++)
    {
        double diff = timings[i] - mean;
        variance += diff * diff;
    }
    double stddev = Math.Sqrt(variance / timings.Length);

    Console.WriteLine($"{name,-35} {mean,12:F1} {stddev,12:F1}");
}

// Overloads for value-returning lambdas
[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<double> action) => Bench(name, () => (object?)action());
[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<int> action) => Bench(name, () => (object?)action());

