[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<object?> action)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Collect individual timings
    var sw = new Stopwatch();
    double[] timings = new double[iterations];
    for (int i = 0; i < iterations; i++)
    {
        sw.Restart();
        action();
        sw.Stop();
        timings[i] = sw.Elapsed.TotalNanoseconds;
    }

    double mean = 0;
    for (int i = 0; i < timings.Length; i++) mean += timings[i];
    mean /= timings.Length;

    double variance = 0;
    for (int i = 0; i < timings.Length; i++)
    {
        double diff = timings[i] - mean;
        variance += diff * diff;
    }
    double stddev = Math.Sqrt(variance / timings.Length);

    Console.WriteLine($"{name,-35} {mean,12:F1} {stddev,12:F1}");
}

arguments.new_str:
[MethodImpl(MethodImplOptions.NoInlining)]
static void Bench(string name, Func<object?> action)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Batch timing: run batchSize iterations per sample to amortize timer overhead
    const int batchSize = 200;
    int samples = iterations / batchSize;
    var sw = new Stopwatch();
    double[] timings = new double[samples];
    for (int s = 0; s < samples; s++)
    {
        sw.Restart();
        for (int i = 0; i < batchSize; i++) action();
        sw.Stop();
        timings[s] = sw.Elapsed.TotalNanoseconds / batchSize;
    }

    Array.Sort(timings);
    double median = timings[samples / 2];

    // IQR-based: use middle 50% for mean
    int q1 = samples / 4;
    int q3 = samples * 3 / 4;
    double trimmedMean = 0;
    for (int i = q1; i < q3; i++) trimmedMean += timings[i];
    trimmedMean /= (q3 - q1);

    Console.WriteLine($"{name,-35} {median,12:F1} {trimmedMean,12:F1}");
}

